import java.util.Scanner;

public class Main {
    public static double myAbs(double val) {
        return (val < 0) ? -val : val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();

        int num = 0, den = 1;
        double bestDiffValue = 1e15;
        double targetValue = (double) x / y;

        for (int j = 1; j <= n; ++j) {
            int low = 0, high = 1000000000;
            while (high - low > 10) {
                int mid1 = low + (high - low) / 3;
                int mid2 = high - (high - low) / 3;
                double diff1 = myAbs(targetValue - (double) mid1 / j);
                double diff2 = myAbs(targetValue - (double) mid2 / j);
                if (diff1 > diff2)
                    low = mid1;
                else
                    high = mid2;
            }
            for (int i = low; i <= high + 3; ++i) {
                double currentDiff = myAbs(targetValue - (double) i / j);
                if (currentDiff < bestDiffValue - 1e-15) {
                    bestDiffValue = currentDiff;
                    num = i;
                    den = j;
                }
            }
        }
        System.out.println(num + "/" + den);
        sc.close();
    }
}
